'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const records=[
['Linh Phương','Facebook',2,'AI marketing đang thay đổi cách mình xây dựng nội dung. Từ nghiên cứu khách hàng đến thử nghiệm thông điệp, điều quan trọng vẫn là hiểu đúng nhu cầu người đọc. #AIMarketing',1240,243,156,'positive','image','vi'],
['Minh Đức','X',5,'AI không thay thế marketer, nhưng marketer biết dùng AI sẽ có lợi thế. Chia sẻ quy trình AI marketing: nghiên cứu → lên ý tưởng → biên tập → đo lường. #ContentAI',892,120,98,'positive','text','vi'],
['Thảo Vy','Threads',19,'Đang thử AI marketing cho một thương hiệu nhỏ. Tiết kiệm thời gian lên dàn ý, nhưng phần giọng văn và kiểm chứng thông tin vẫn cần tự làm. Mọi người dùng công cụ nào?',456,67,23,'neutral','text','vi'],
['Growth Notes','X',28,'AI marketing works best when the team has a clear measurement framework. Start with one use case and compare outcomes. #AIMarketing',315,41,56,'positive','text','en'],
['Quang Huy','Facebook',57,'Có ai thấy nội dung AI marketing ngày càng giống nhau? Nếu chỉ chạy theo số lượng thì rất khó xây dựng bản sắc thương hiệu. #ContentAI',215,88,14,'negative','text','vi'],
['Mai Anh','Threads',100,'Ghi chú sau một tuần thử AI marketing: dùng để tìm góc nhìn mới, giữ bản nháp ngắn, và luôn kiểm tra nguồn. Chất lượng phản hồi quan trọng hơn lượt xem.',687,92,31,'positive','image','vi'],
['Commerce Lab','Facebook',8,'Social commerce: người mua cần nội dung giải đáp câu hỏi thực tế trước khi quyết định. Livestream có hiệu quả hơn khi có một cộng đồng tin tưởng. #SocialCommerce',1530,185,90,'positive','image','vi'],
['Tuấn Nguyễn','Threads',34,'Mình đang tìm hiểu social commerce cho cửa hàng đồ thủ công. Có nên bắt đầu từ video ngắn hay nội dung chia sẻ quá trình làm sản phẩm?',128,52,8,'neutral','text','vi'],
['Lan Trần','Facebook',10,'Mình cần mua laptop để học thiết kế, ngân sách khoảng 20 triệu. Ưu tiên màn hình tốt và máy nhẹ. Xin mọi người gợi ý cấu hình phù hợp.',95,63,4,'neutral','text','vi'],
['Nam Bùi','X',42,'Cần mua laptop làm việc từ xa, ưu tiên pin bền và bàn phím tốt. Có mẫu nào đáng cân nhắc trong tầm 15 triệu không?',42,18,3,'neutral','text','vi'],
['Digital Weekly','Threads',230,'Tổng hợp thử nghiệm AI marketing tháng này: bắt đầu từ insight, sau đó mới chọn công cụ. #AIMarketing #ContentAI',380,29,47,'positive','image','vi'],
['Marketing Studio','Facebook',15,'Quảng cáo khóa học AI marketing cho người mới. Lộ trình xây dựng nội dung và đo lường chiến dịch. #AIMarketing',82,12,6,'neutral','image','vi'],
['Content Circle','X',72,'ContentAI giúp tăng tốc bản nháp. Một bài viết hữu ích vẫn cần trải nghiệm thực tế, ví dụ rõ ràng và dữ liệu có nguồn. #ContentAI',267,31,22,'positive','text','vi'],
['Studio Mộc','Threads',160,'Social commerce không chỉ là bán hàng trong buổi livestream. Chăm sóc sau mua và phản hồi bình luận cũng là một phần trải nghiệm. #SocialCommerce',311,47,12,'positive','image','vi']
].map((r,id)=>({id,name:r[0],platform:r[1],hours:r[2],text:r[3],likes:r[4],comments:r[5],shares:r[6],sentiment:r[7],type:r[8],language:r[9]}));
function read(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback}catch{return fallback}}let saved=read('sr-saved',[]),queries=read('sr-queries',[]),view='search',activePlatforms=new Set(['Facebook','X','Threads']),filtered=[];const logos={Facebook:'f',X:'𝕏',Threads:'@'},navItems=[['overview','◫','Tổng quan'],['search','⌕','Tìm kiếm'],['saved','♧','Bộ sưu tập'],['trending','↗','Xu hướng'],['reports','▤','Báo cáo'],['settings','⚙','Cài đặt']];
function persist(){try{localStorage.setItem('sr-saved',JSON.stringify(saved));localStorage.setItem('sr-queries',JSON.stringify(queries))}catch{toast('Trình duyệt không cho lưu dữ liệu.')}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function modal(title,body){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;$('#dialog').showModal()}
function sources(){modal('Nguồn dữ liệu',`<p>Chưa có nền tảng nào được kết nối. Các bài và chỉ số hiện tại là dữ liệu minh họa, không phải kết quả thu thập trực tiếp.</p>${['Facebook','X','Threads'].map(p=>`<div class="connection"><strong>${logos[p]} &nbsp; ${p}</strong><span>Chưa kết nối</span></div>`).join('')}<h3>Bước tiếp theo</h3><p>Kiểm chứng quyền tìm kiếm của ứng dụng, gói API và hạn mức từng nền tảng. Sau đó cấu hình khóa ở backend và thêm lịch thu thập. Không nhập khóa API vào bản trải nghiệm này.</p><p>Bản hiện tại lưu bài và truy vấn trong trình duyệt; chưa có đồng bộ tài khoản hoặc tác vụ chạy nền.</p>`)}
function normalize(s){return s.toLocaleLowerCase('vi').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d')}
function terms(s){return (s.match(/"[^"]+"|\S+/g)||[]).map(t=>normalize(t.replace(/^"|"$/g,'')))}
const engagement=p=>p.likes+p.comments+p.shares,fmt=n=>new Intl.NumberFormat('vi-VN').format(n);
function render(){
const tokens=terms($('#query').value),excluded=$('#exclude').value.split(',').map(s=>normalize(s.trim())).filter(Boolean),min=Math.max(0,Number($('#minEng').value)||0),type=$('#contentType').value,lang=$('#language').value;
filtered=records.filter(p=>{let text=normalize(p.text);return activePlatforms.has(p.platform)&&p.hours<=Number($('#days').value)*24&&tokens.every(t=>text.includes(t))&&!excluded.some(t=>text.includes(t))&&engagement(p)>=min&&(type==='all'||p.type===type)&&(lang==='all'||p.language===lang)&&(view!=='saved'||saved.includes(p.id))});
filtered.sort((a,b)=>$('#sort').value==='engagement'?engagement(b)-engagement(a):$('#sort').value==='relevance'?(terms($('#query').value).reduce((s,t)=>s+(normalize(b.text).split(t).length-normalize(a.text).split(t).length),0)||a.hours-b.hours):a.hours-b.hours);
$('#nav').innerHTML=navItems.map(([id,icon,label])=>`<button data-nav="${id}" class="${view===id?'active':''}"><span>${icon}</span>${label}${id==='saved'&&saved.length?` · ${saved.length}`:''}</button>`).join('');
$('#platforms').innerHTML=Object.keys(logos).map(p=>`<button type="button" data-platform="${p}" class="${activePlatforms.has(p)?'on':''}" aria-pressed="${activePlatforms.has(p)}"><span class="plogo">${logos[p]}</span>${p}</button>`).join('');
$('#resultTitle').textContent=view==='saved'?'Bài viết đã lưu':'Kết quả tìm kiếm';$('#resultCount').textContent=`${filtered.length} bài viết mẫu`;
const total=filtered.reduce((s,p)=>s+engagement(p),0),pos=filtered.filter(p=>p.sentiment==='positive').length,pct=filtered.length?Math.round(pos/filtered.length*100):0;
$('#metrics').innerHTML=[['▤','Kết quả phù hợp',fmt(filtered.length),'Bài viết trong dữ liệu mẫu'],['♡','Tổng tương tác',fmt(total),'Lượt thích, bình luận, chia sẻ'],['⌁','Nền tảng có kết quả',new Set(filtered.map(p=>p.platform)).size+'/3','Theo các bộ lọc hiện tại'],['☺','Nhãn tích cực',pct+'%','Tỷ lệ nhãn mẫu trong kết quả']].map(([icon,label,value,caption],i)=>`<article class="metric"><div class="metricTop"><span class="metricIcon">${icon}</span>${label}</div><strong>${value}</strong><small>${caption}</small><svg viewBox="0 0 90 40" aria-hidden="true"><path d="M0 35 L12 28 L23 31 L37 18 L47 22 L60 9 L72 14 L90 2" fill="none" stroke="${['#9c8aff','#8ab8ff','#56dab4','#b18bed'][i]}" stroke-width="2"/></svg></article>`).join('');
$('#results').innerHTML=filtered.length?filtered.map(p=>`<article class="post"><div class="avatar" style="background:hsl(${p.id*43+230} 25% 30%)">${esc(p.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</div><div class="postbody"><div class="postmeta"><strong>${esc(p.name)}</strong><small>· ${p.hours<24?p.hours+' giờ':Math.floor(p.hours/24)+' ngày'} trước</small><span class="platformtag">${logos[p.platform]} ${p.platform}</span></div><p class="posttext">${esc(p.text)}</p><div class="postbottom"><span>♡ ${fmt(p.likes)}</span><span>♧ ${fmt(p.comments)}</span><span>↗ ${fmt(p.shares)}</span><span class="tag">${p.type==='image'?'Có hình ảnh':'Văn bản'}</span><button data-save="${p.id}" class="${saved.includes(p.id)?'saved':''}" aria-label="${saved.includes(p.id)?'Bỏ lưu':'Lưu bài'}" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'◆':'◇'}</button></div></div></article>`).join(''):`<div class="empty"><strong>${view==='saved'?'Chưa có bài đã lưu phù hợp':'Chưa tìm thấy nội dung phù hợp'}</strong>Thử giảm bộ lọc hoặc đổi từ khóa.<br>Dữ liệu minh họa gồm AI marketing, social commerce và nhu cầu mua laptop.<br><button data-clear style="margin-top:16px">Xem tất cả dữ liệu mẫu</button></div>`;
$('#donutCount').textContent=filtered.length;let counts=['positive','neutral','negative'].map(s=>filtered.filter(p=>p.sentiment===s).length),colors=['#56dab4','#9287ce','#f48a9f'];$('#legend').innerHTML=counts.map((n,i)=>`<div><span><i style="background:${colors[i]}"></i>${['Tích cực','Trung lập','Tiêu cực'][i]}</span><strong>${n} bài</strong></div>`).join('');let a=filtered.length?counts[0]/filtered.length*100:0,b=filtered.length?(counts[0]+counts[1])/filtered.length*100:0;$('.donut').style.background=filtered.length?`conic-gradient(${colors[0]} 0 ${a}%,${colors[1]} ${a}% ${b}%,${colors[2]} ${b}% 100%)`:'#29344b';
const tags={};filtered.forEach(p=>(p.text.match(/#[\p{L}\p{N}]+/gu)||[]).forEach(tag=>tags[tag]=(tags[tag]||0)+1));$('#trends').innerHTML=Object.entries(tags).sort((a,b)=>b[1]-a[1]).slice(0,4).map(([tag,n],i)=>`<button class="trendrow" data-query="${esc(tag)}"><span class="rank">0${i+1}</span><div><strong>${esc(tag)}</strong><small>${n} bài trong kết quả</small></div><span class="rise">↗</span></button>`).join('')||'<p class="small" style="padding:20px 0">Chưa có hashtag trong kết quả.</p>';
$('#filterBadge').textContent=[excluded.length>0,min>0,type!=='all',lang!=='all'].filter(Boolean).length||'';
}
function reset(){activePlatforms=new Set(Object.keys(logos));$('#query').value='';$('#exclude').value='';$('#minEng').value=0;$('#contentType').value='all';$('#language').value='all';$('#days').value='365';render()}
function exportCSV(){if(!filtered.length)return toast('Chưa có kết quả để xuất.');let rows=[['Nguồn dữ liệu','Nền tảng','Tác giả','Nội dung','Lượt thích','Bình luận','Chia sẻ'],...filtered.map(p=>['MINH HỌA',p.platform,p.name,p.text,p.likes,p.comments,p.shares])];const safe=v=>{let s=String(v);if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};let blob=new Blob(['\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='social-radar-du-lieu-minh-hoa.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Đã xuất '+filtered.length+' kết quả mẫu.')} 
$('#searchForm').onsubmit=e=>{e.preventDefault();render();toast('Đã lọc dữ liệu minh họa.')};$('#advanced').onclick=()=>{$('#advancedPanel').hidden=!$('#advancedPanel').hidden;$('#advanced').setAttribute('aria-expanded',!$('#advancedPanel').hidden)};$('#reset').onclick=reset;['days','contentType','language','sort'].forEach(id=>$('#'+id).onchange=render);['exclude','minEng'].forEach(id=>$('#'+id).oninput=render);$('#export').onclick=exportCSV;$('#connect').onclick=sources;$('#sourceButton').onclick=sources;$('#demoInfo').onclick=sources;$('#closeDialog').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog'))$('#dialog').close()};$('#saveQuery').onclick=()=>{const q={query:$('#query').value,platforms:[...activePlatforms],days:$('#days').value,exclude:$('#exclude').value,min:$('#minEng').value,type:$('#contentType').value,lang:$('#language').value};if(!queries.some(x=>JSON.stringify(x)===JSON.stringify(q)))queries.push(q);persist();toast('Đã lưu truy vấn trên trình duyệt.');};
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.platform){let p=b.dataset.platform;activePlatforms.has(p)?activePlatforms.delete(p):activePlatforms.add(p);render()}if(b.dataset.save!==undefined){let id=Number(b.dataset.save);saved.includes(id)?saved=saved.filter(x=>x!==id):saved.push(id);persist();render()}if(b.dataset.query!==undefined){$('#query').value=b.dataset.query;render()}if(b.hasAttribute('data-clear'))reset();if(b.dataset.restore!==undefined){let q=queries[Number(b.dataset.restore)];$('#query').value=q.query;activePlatforms=new Set(q.platforms);$('#days').value=q.days;$('#exclude').value=q.exclude;$('#minEng').value=q.min;$('#contentType').value=q.type;$('#language').value=q.lang;$('#dialog').close();view='search';render()}if(b.dataset.nav){let v=b.dataset.nav;if(v==='settings')return sources();if(v==='reports')return modal('Báo cáo & truy vấn đã lưu',`<p>Xuất CSV theo bộ lọc hiện tại. Các con số chỉ phản ánh dữ liệu minh họa.</p><button id="modalExport">↧ Xuất ${filtered.length} kết quả mẫu</button><h3>Truy vấn đã lưu (${queries.length})</h3>${queries.length?queries.map((q,i)=>`<button class="savedquery" data-restore="${i}">${esc(q.query||'Tất cả từ khóa')}<small>${esc(q.platforms.join(', '))} · ${q.days} ngày</small></button>`).join(''):'<p>Nhấn “Lưu truy vấn” sau khi chọn bộ lọc để dùng lại.</p>'}`);view=v;$('#title').innerHTML=v==='saved'?'Những tín hiệu <em>bạn đã lưu.</em>':v==='trending'?'Khám phá <em>chủ đề nổi bật.</em>':v==='overview'?'Bức tranh <em>cuộc trò chuyện.</em>':'Khám phá những <em>tín hiệu mới.</em>';$('#subtitle').textContent=v==='saved'?'Bộ sưu tập cá nhân trên trình duyệt này. Bộ lọc hiện tại vẫn được áp dụng.':'Tìm kiếm có chọn lọc. Hiểu cuộc trò chuyện. Đón đầu xu hướng.';render();if(v==='trending')$('.trend').scrollIntoView({behavior:'smooth',block:'center'})}if(b.id==='modalExport')exportCSV()});render();
